// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: the inline AI box (Alt+I) of a pane whose content is a framed page (today the
//          Terminal): shown in the pane's title strip, left of its buttons, so it never covers
//          the content (spec/services/ui/README.md, "Toggles don't move the content"). The box is the shared one
//          (ui/inline_box.js); the framed page does its own part (the Terminal's: read the
//          screen, ask the AI, paste the command; ui/terminal.py). They talk by postMessage.
// Usage: a pane puts ui.strip_ask() in its strip; Alt+I in its page, or its ✨ button
//        (assets/panes.js calls window.smashFrameAsk.toggle(pane)), opens the box.
// ---------------------------------------------------------------------------
//
// Messages (page = the pane's framed page):
//   page -> app  {type: "delulu-ask-toggle"}                    Alt+I pressed inside it
//   app -> page  {type: "delulu-ask-send", id, ask}             Enter in the box
//   page -> app  {type: "delulu-ask-answer", id, command | error | note | pasted}
//   app -> page  {type: "delulu-ask-paste", id, command}        the answer to use (the Terminal
//                                                               types it at the prompt, never runs
//                                                               it, and answers `pasted`, or `error`
//                                                               when it no longer can)
// The page only takes messages from this machine's pages (terminal.py: its origin check).
(() => {
  const HINT = "Enter asks AI · Esc closes";
  const frameOf = (pane) => pane.querySelector("iframe");
  const boxes = new Map();  // pane -> { shell, asked, waiting }: one box per pane, made on first open

  async function make(pane, spot) {
    // the shared box, served to the app as a Reflex shared asset (editor.py)
    const { inlineBox } = await import("/external/ui/editor/inline_box.js");
    const shell = inlineBox({ placeholder: spot.dataset.placeholder || "Ask AI…", hint: HINT });
    // the framed page's AI knows nothing of Python variables: no "@" mentions (mentions.js)
    shell.input.dataset.noMentions = "";
    const state = { shell, asked: 0, waiting: false };
    shell.input.addEventListener("keydown", (event) => {
      // Alt+I again closes it, as in a cell (the app's other Alt keys pass on)
      if (event.altKey && event.code === "KeyI" && !event.shiftKey && !event.ctrlKey && !event.metaKey) {
        event.preventDefault();
        event.stopPropagation();
        return close(pane);
      }
      if (event.altKey || event.ctrlKey || event.metaKey) return;
      if (event.key === "Enter") { event.preventDefault(); send(pane); }
      if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); close(pane); }
    });
    spot.append(shell.dom);
    boxes.set(pane, state);
    return state;
  }

  const making = new Map();  // pane -> its box being made: a second Alt+I meanwhile waits for it
  async function open(pane) {
    const spot = pane.querySelector("[data-strip-ask]");
    if (!spot) return;
    if (!boxes.has(pane)) {
      if (!making.has(pane)) making.set(pane, make(pane, spot));
      await making.get(pane);
      making.delete(pane);
    }
    const { shell, waiting } = boxes.get(pane);
    shell.dom.hidden = false;
    if (!waiting) { shell.input.disabled = false; shell.input.value = ""; shell.say(HINT); }
    shell.input.focus();
  }

  function close(pane) {
    const state = boxes.get(pane);
    if (!state) return;
    state.shell.dom.hidden = true;
    if (state.waiting) { state.asked++; state.waiting = false; state.shell.thinking(false); }
    // back to the page, unless you have moved to another pane meanwhile (a late answer must
    // not pull the cursor, and your typing, into the shell)
    const at = document.activeElement;
    const frame = frameOf(pane);
    if (frame && (!at || at === document.body || pane.contains(at))) window.smashFocusFrame?.(frame);
  }

  const isOpen = (pane) => {
    const state = boxes.get(pane);
    return Boolean(state && !state.shell.dom.hidden);
  };
  const toggle = (pane) => (isOpen(pane) ? close(pane) : open(pane));

  function send(pane) {
    const state = boxes.get(pane);
    const ask = state.shell.input.value.trim();
    const frame = frameOf(pane);
    if (!ask || state.waiting || !frame) return;
    state.waiting = true;
    state.shell.input.disabled = true;
    state.shell.say("Thinking…");
    state.shell.thinking(true);
    frame.contentWindow.postMessage({ type: "delulu-ask-send", id: ++state.asked, ask }, "*");
  }

  function answered(pane, data) {
    const state = boxes.get(pane);
    if (!state || data.id !== state.asked || !state.waiting) return;  // an ask closed since
    if (data.command) {
      // still waiting: the page answers `pasted`, or an error if it can't type it any more
      const message = { type: "delulu-ask-paste", id: data.id, command: data.command };
      return frameOf(pane)?.contentWindow.postMessage(message, "*");
    }
    state.waiting = false;
    state.shell.input.disabled = false;
    state.shell.thinking(false);
    if (data.pasted) return close(pane);
    state.shell.say(data.error || data.note || "no answer", data.error ? "error" : "note");
    state.shell.input.focus();
    state.shell.input.select();
  }

  // only a pane's own framed page is listened to
  window.addEventListener("message", (event) => {
    if (!event.data) return;
    const pane = [...document.querySelectorAll("[data-pane]")].find((node) => frameOf(node)?.contentWindow === event.source);
    if (!pane) return;
    if (event.data.type === "delulu-ask-toggle") toggle(pane);
    if (event.data.type === "delulu-ask-answer") answered(pane, event.data);
  });

  window.smashFrameAsk = { toggle };
})();
